from __future__ import annotations
from dataclasses import dataclass

@dataclass(frozen=True)
class Bound:
    total: int
    describable_at_most: int
    incompressible_at_least: int
    incompressible_fraction_at_least: float

def counting_bound(alphabet_size: int, length: int, programs: int) -> Bound:
    if min(alphabet_size, length, programs) < 0:
        raise ValueError("inputs must be nonnegative")
    total = alphabet_size ** length
    described = min(total, programs)
    missing = total - described
    return Bound(total, described, missing, missing / total if total else 0.0)

if __name__ == "__main__":
    for c in (1, 5, 10, 20):
        result = counting_bound(2, 64, 2 ** (64 - c))
        print(c, result)

from __future__ import annotations
from typing import TypeVar, Sequence
T = TypeVar("T")

def distance(x: Sequence[T], y: Sequence[T]) -> int:
    if len(x) != len(y):
        raise ValueError("equal lengths required")
    return sum(a != b for a, b in zip(x, y))

def shortest_path(x: Sequence[T], y: Sequence[T]) -> list[tuple[T, ...]]:
    if len(x) != len(y):
        raise ValueError("equal lengths required")
    current = list(x)
    path = [tuple(current)]
    for i, symbol in enumerate(y):
        if current[i] != symbol:
            current[i] = symbol
            path.append(tuple(current))
    return path

if __name__ == "__main__":
    path = shortest_path("BABEL", "BOOKS")
    print("distance =", distance("BABEL", "BOOKS"))
    print(" -> ".join("".join(word) for word in path))

