from __future__ import annotations
from itertools import product
import networkx as nx
import matplotlib.pyplot as plt

def hamming_graph(A: int, L: int) -> nx.Graph:
    vertices = list(product(range(A), repeat=L))
    graph = nx.Graph(); graph.add_nodes_from(vertices)
    for word in vertices:
        for i in range(L):
            for symbol in range(A):
                if symbol != word[i]:
                    neighbor = word[:i] + (symbol,) + word[i+1:]
                    graph.add_edge(word, neighbor)
    return graph

if __name__ == "__main__":
    graph = hamming_graph(2, 3)
    nx.draw_networkx(graph, pos=nx.spring_layout(graph, seed=4),
                     node_color="#2a9d8f", font_size=7)
    plt.title("Connected Hamming graph H(2,3)")
    plt.axis("off"); plt.tight_layout(); plt.savefig("hamming_graph.png", dpi=180)

